package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.block.Block;
import net.minecraft.util.math.BlockPos;
/** Actual authored joining axes, diagonal steps, floor/ceiling input rows and retired alias. */
public final class ScreenJoinGeometryLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();java.util.List<BlockAnimatedScreenSelector> blocks=new java.util.ArrayList<>();for(String id:ScreenFamilyLegacyChecks.IDS)for(Block block:ModBlocks.BLOCKS)if(block.getRegistryName().getResourcePath().equals(id))blocks.add((BlockAnimatedScreenSelector)block);blocks.add(new BlockDiagonalHalfConsole("programmable_diagonal_half_console"));JsonArray output=new JsonArray();for(BlockAnimatedScreenSelector block:blocks)for(IBlockState state:block.getBlockState().getValidStates())for(boolean ceiling:new boolean[]{false,true})for(boolean small:new boolean[]{false,true}){TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);tile.setCeilingMounted(ceiling);tile.setSmallInput(small);NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);BlockPos pos=new BlockPos(0,80,0);world.states.put(pos,state);world.tiles.put(pos,tile);tile.setWorld(world);tile.setPos(pos);DisplayJoinGeometry.Basis basis=DisplayJoinGeometry.basis(tile,state);JsonObject row=new JsonObject();row.addProperty("id",block.getRegistryName().getResourcePath());row.addProperty("meta",block.getMetaFromState(state));row.addProperty("ceiling",ceiling);row.addProperty("small",small);row.addProperty("supported",DisplayJoinGeometry.supportsJoining(tile));row.addProperty("right",basis.right.getIndex());row.addProperty("up",basis.up.getIndex());JsonArray steps=new JsonArray();for(BlockPos step:basis.steps){JsonArray point=new JsonArray();point.add(step.getX());point.add(step.getY());point.add(step.getZ());steps.add(point);}row.add("steps",steps);JsonArray cells=new JsonArray();for(BlockPos probe:new BlockPos[]{new BlockPos(-2,79,3),pos,new BlockPos(3,81,-5)})cells.add(basis.cell(probe));row.add("cells",cells);output.add(row);}
  String serialized=output.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte b:hash.digest(serialized.getBytes("UTF-8")))digest.append(String.format("%02x",b&255));if(!digest.toString().equals("5496c7a4292d4e2ce8513af3398430e7938bf5b3eb07d59526c0bdbd570ecad0"))throw new AssertionError("Actual joining basis changed "+digest);JsonObject reference=new JsonObject();reference.addProperty("sha256",digest.toString());reference.add("cases",output);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-join-geometry-reference.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.write(path,reference.toString().getBytes("UTF-8"));System.out.println("Actual Screen join geometry reference PASS cases="+output.size()+" sha256="+digest);
 }
}
